    // Also update on the widget control
    self.DOMObject.find('.form-control[name="name"]').on('change', function (ev) {
      const $select = self.DOMObject.find('.canvas-widget-control select');

      // Update option
      $select.find('option[selected]').html($(ev.currentTarget).val());

      // Reload select2
      makeLocalSelect($select);
    });
