  const checkHistory = this.checkHistory();
  const undoActiveTitle = checkHistory ? checkHistory.undoActiveTitle : '';
  const $undoButton = pE.editorContainer.find('.footer-actions [data-action="undo"]');

  // Toggle active
  $undoButton.toggleClass('inactive', !checkHistory.undoActive);

  // Update title
  $undoButton.attr('title', undoActiveTitle);

  // Delete object - Widget button
